def get_user_profile(account_id, refresh=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_user_profile"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_account_id=None, error_code=None, error_message=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "xt_req_" + _gen_id_suffix(18),
                "endpoint": endpoint,
                "account_id": used_account_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now()
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _gen_id_suffix(n=18):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "".join(random.choice(alphabet) for _ in range(n))

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _quota_check(account_id_for_log=None):
        # Basic rolling rate limit: 60 req/min per account; if no account, global 120/min.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return None
            now = datetime.datetime.utcnow()
            window = now - datetime.timedelta(seconds=60)
            cnt = 0
            cnt_global = 0
            for r in reversed(logs[-2000:]):
                ts = _parse_dt(r.get("created_at"))
                if not ts:
                    continue
                if ts < window:
                    continue
                cnt_global += 1
                if account_id_for_log and r.get("account_id") == account_id_for_log:
                    cnt += 1
            if account_id_for_log and cnt >= 60:
                return _err("RATE_LIMIT", "Rate limit exceeded for this account (60 requests/min).")
            if cnt_global >= 120:
                return _err("RATE_LIMIT", "Global rate limit exceeded (120 requests/min).")
            return None
        except Exception:
            return None

    def _find_account(accts, acct_id):
        for a in accts:
            if isinstance(a, dict) and a.get("id") == acct_id:
                return a
        return None

    def _upsert_user(users, x_id, screen_name, display_name=None):
        # Enforce unique(x_id) and unique(lower(screen_name))
        lx = (screen_name or "").lower()
        existing_by_x = None
        for u in users:
            if isinstance(u, dict) and u.get("x_id") == x_id:
                existing_by_x = u
                break
        existing_by_sn = None
        for u in users:
            if isinstance(u, dict) and (u.get("screen_name") or "").lower() == lx and lx:
                existing_by_sn = u
                break

        now = _now()
        if existing_by_x:
            # If screen name belongs to a different x_id, conflict.
            if existing_by_sn and existing_by_sn is not existing_by_x:
                return None, _err("CONFLICT", "screen_name is already used by a different user.", screen_name=screen_name)
            existing_by_x["screen_name"] = screen_name
            existing_by_x["display_name"] = display_name
            if existing_by_x.get("verified_type") not in ("none", "blue", "business", "government"):
                existing_by_x["verified_type"] = "none"
            if not isinstance(existing_by_x.get("protected"), bool):
                existing_by_x["protected"] = False
            existing_by_x["last_fetched_at"] = now
            existing_by_x["updated_at"] = now
            return existing_by_x, None

        # If screen_name exists with different x_id, conflict.
        if existing_by_sn and existing_by_sn.get("x_id") != x_id:
            return None, _err("CONFLICT", "screen_name is already used by a different user.", screen_name=screen_name)

        new_u = {
            "id": "xt_usr_" + _gen_id_suffix(18),
            "x_id": x_id,
            "screen_name": screen_name,
            "display_name": display_name,
            "bio": None,
            "location": None,
            "profile_image_url": None,
            "verified_type": "none",
            "protected": False,
            "followers_count": None,
            "following_count": None,
            "statuses_count": None,
            "favourites_count": None,
            "joined_at": None,
            "last_fetched_at": now,
            "created_at": now,
            "updated_at": now
        }
        users.append(new_u)
        return new_u, None

    # ---- Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{17,}$", account_id):
        _log("error", used_account_id=account_id, error_code="VALIDATION_ERROR", error_message="account_id is missing or invalid.")
        return _err("VALIDATION_ERROR", "account_id is missing or invalid.")
    if refresh is not None and not isinstance(refresh, bool):
        _log("error", used_account_id=account_id, error_code="VALIDATION_ERROR", error_message="refresh must be boolean.")
        return _err("VALIDATION_ERROR", "refresh must be boolean.")

    rl = _quota_check(account_id)
    if rl:
        _log("error", used_account_id=account_id, error_code=rl["error"]["code"], error_message=rl["error"]["message"])
        return rl

    accounts = _load("accounts.json")
    users = _load("users.json")
    if not isinstance(accounts, list): accounts = []
    if not isinstance(users, list): users = []

    acct = _find_account(accounts, account_id)
    if not acct:
        _log("error", used_account_id=account_id, error_code="NOT_FOUND", error_message="Account not found.")
        return _err("NOT_FOUND", "Account not found.")
    if acct.get("status") != "active":
        _log("error", used_account_id=account_id, error_code="UNAUTHORIZED", error_message="Account is not active/usable.")
        return _err("UNAUTHORIZED", "Account is not active/usable.")

    x_uid = acct.get("x_user_id")
    if not isinstance(x_uid, str) or not x_uid:
        _log("error", used_account_id=account_id, error_code="VALIDATION_ERROR", error_message="Account is missing x_user_id.")
        return _err("VALIDATION_ERROR", "Account is missing x_user_id.")

    # Locate cached user row for account
    urow = None
    for u in users:
        if isinstance(u, dict) and u.get("x_id") == x_uid:
            urow = u
            break

    # If missing or refresh requested, "fetch from X" and upsert
    if urow is None or refresh is True:
        # Offline "fetch": rely on cached account fields as source of truth for profile basics.
        screen_name = acct.get("screen_name")
        if not isinstance(screen_name, str) or not screen_name.strip():
            _log("error", used_account_id=account_id, error_code="VALIDATION_ERROR", error_message="Account has empty screen_name.")
            return _err("VALIDATION_ERROR", "Account has empty screen_name.")
        display_name = acct.get("display_name") if isinstance(acct.get("display_name"), str) else None

        urow2, e = _upsert_user(users, x_uid, screen_name.strip(), display_name=display_name)
        if e:
            _log("error", used_account_id=account_id, error_code=e["error"]["code"], error_message=e["error"]["message"])
            return e
        urow = urow2
        _save("users.json", users)

    # Update account last_used_at/updated_at
    now = _now()
    acct["last_used_at"] = now
    acct["updated_at"] = now
    _save("accounts.json", accounts)

    _log("ok", used_account_id=account_id)
    return {
        "data": urow,
        "meta": {
            "account_id": account_id,
            "refreshed": bool(refresh),
            "timestamp": now
        }
    }

def get_user_by_screen_name(screen_name, account_id=None, refresh=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_user_by_screen_name"

    def _gen_id_suffix(n=18):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "".join(random.choice(alphabet) for _ in range(n))

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, used_account_id=None, error_code=None, error_message=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "xt_req_" + _gen_id_suffix(18),
                "endpoint": endpoint,
                "account_id": used_account_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now()
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _quota_check(account_id_for_log=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return None
            now = datetime.datetime.utcnow()
            window = now - datetime.timedelta(seconds=60)
            cnt = 0
            cnt_global = 0
            for r in reversed(logs[-2000:]):
                ts = _parse_dt(r.get("created_at"))
                if not ts or ts < window:
                    continue
                cnt_global += 1
                if account_id_for_log and r.get("account_id") == account_id_for_log:
                    cnt += 1
            if account_id_for_log and cnt >= 60:
                return _err("RATE_LIMIT", "Rate limit exceeded for this account (60 requests/min).")
            if cnt_global >= 120:
                return _err("RATE_LIMIT", "Global rate limit exceeded (120 requests/min).")
            return None
        except Exception:
            return None

    def _find_account(accts, acct_id):
        for a in accts:
            if isinstance(a, dict) and a.get("id") == acct_id:
                return a
        return None

    def _upsert_user(users, x_id, sn, display_name=None):
        lx = (sn or "").lower()
        existing_by_x = None
        for u in users:
            if isinstance(u, dict) and u.get("x_id") == x_id:
                existing_by_x = u
                break
        existing_by_sn = None
        for u in users:
            if isinstance(u, dict) and (u.get("screen_name") or "").lower() == lx and lx:
                existing_by_sn = u
                break

        now = _now()
        if existing_by_x:
            if existing_by_sn and existing_by_sn is not existing_by_x:
                return None, _err("CONFLICT", "screen_name is already used by a different user.", screen_name=sn)
            existing_by_x["screen_name"] = sn
            existing_by_x["display_name"] = display_name
            if existing_by_x.get("verified_type") not in ("none", "blue", "business", "government"):
                existing_by_x["verified_type"] = "none"
            if not isinstance(existing_by_x.get("protected"), bool):
                existing_by_x["protected"] = False
            existing_by_x["last_fetched_at"] = now
            existing_by_x["updated_at"] = now
            return existing_by_x, None

        if existing_by_sn and existing_by_sn.get("x_id") != x_id:
            return None, _err("CONFLICT", "screen_name is already used by a different user.", screen_name=sn)

        new_u = {
            "id": "xt_usr_" + _gen_id_suffix(18),
            "x_id": x_id,
            "screen_name": sn,
            "display_name": display_name,
            "bio": None,
            "location": None,
            "profile_image_url": None,
            "verified_type": "none",
            "protected": False,
            "followers_count": None,
            "following_count": None,
            "statuses_count": None,
            "favourites_count": None,
            "joined_at": None,
            "last_fetched_at": now,
            "created_at": now,
            "updated_at": now
        }
        users.append(new_u)
        return new_u, None

    # ---- Validate
    if not isinstance(screen_name, str) or len(screen_name.strip()) < 1:
        _log("error", used_account_id=account_id, error_code="VALIDATION_ERROR", error_message="screen_name is missing/invalid.")
        return _err("VALIDATION_ERROR", "screen_name is missing/invalid.")
    sn = screen_name.strip().lstrip("@")
    if not sn:
        _log("error", used_account_id=account_id, error_code="VALIDATION_ERROR", error_message="screen_name is missing/invalid.")
        return _err("VALIDATION_ERROR", "screen_name is missing/invalid.")
    if account_id is not None:
        if not isinstance(account_id, str) or not re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{17,}$", account_id):
            _log("error", used_account_id=account_id, error_code="VALIDATION_ERROR", error_message="account_id is invalid.")
            return _err("VALIDATION_ERROR", "account_id is invalid.")
    if refresh is not None and not isinstance(refresh, bool):
        _log("error", used_account_id=account_id, error_code="VALIDATION_ERROR", error_message="refresh must be boolean.")
        return _err("VALIDATION_ERROR", "refresh must be boolean.")

    rl = _quota_check(account_id)
    if rl:
        _log("error", used_account_id=account_id, error_code=rl["error"]["code"], error_message=rl["error"]["message"])
        return rl

    accounts = _load("accounts.json")
    users = _load("users.json")
    if not isinstance(accounts, list): accounts = []
    if not isinstance(users, list): users = []

    acct = None
    if account_id is not None:
        acct = _find_account(accounts, account_id)
        if not acct:
            _log("error", used_account_id=account_id, error_code="NOT_FOUND", error_message="Account not found.")
            return _err("NOT_FOUND", "Account not found.")
        if acct.get("status") != "active":
            _log("error", used_account_id=account_id, error_code="UNAUTHORIZED", error_message="Account is not active/usable.")
            return _err("UNAUTHORIZED", "Account is not active/usable.")

    # Try local cache by screen name
    target = None
    lsn = sn.lower()
    for u in users:
        if isinstance(u, dict) and (u.get("screen_name") or "").lower() == lsn:
            target = u
            break

    # If refresh requested and we have an authenticated context, update from that context when it matches
    # Offline: we cannot actually hit X. We only "refetch" if the requested screen_name equals account screen_name.
    if refresh is True:
        if acct is None:
            _log("error", used_account_id=account_id, error_code="UNAUTHORIZED", error_message="refresh requires a usable account context.")
            return _err("UNAUTHORIZED", "refresh requires a usable account context.")
        acct_sn = (acct.get("screen_name") or "").strip().lstrip("@").lower()
        if acct_sn != lsn:
            # Cannot resolve offline for arbitrary users; treat as not found per contract.
            _log("error", used_account_id=account_id, error_code="NOT_FOUND", error_message="User cannot be resolved for refresh in offline datastore.")
            return _err("NOT_FOUND", "User cannot be resolved.")
        x_id = acct.get("x_user_id")
        if not isinstance(x_id, str) or not x_id:
            _log("error", used_account_id=account_id, error_code="VALIDATION_ERROR", error_message="Account missing x_user_id.")
            return _err("VALIDATION_ERROR", "Account missing x_user_id.")
        target2, e = _upsert_user(users, x_id, sn, display_name=acct.get("display_name") if isinstance(acct.get("display_name"), str) else None)
        if e:
            _log("error", used_account_id=account_id, error_code=e["error"]["code"], error_message=e["error"]["message"])
            return e
        target = target2
        _save("users.json", users)

    if target is None:
        _log("error", used_account_id=account_id, error_code="NOT_FOUND", error_message="User cannot be resolved.")
        return _err("NOT_FOUND", "User cannot be resolved.")

    # Touch account usage if provided
    if acct is not None:
        now = _now()
        acct["last_used_at"] = now
        acct["updated_at"] = now
        _save("accounts.json", accounts)

    _log("ok", used_account_id=account_id)
    return {
        "data": target,
        "meta": {
            "screen_name": sn,
            "refreshed": bool(refresh),
            "timestamp": _now()
        }
    }

def get_user_by_id(user_id=None, x_user_id=None, account_id=None, refresh=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_user_by_id"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _reqlog(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _gen_id("xt_req_"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _is_xt_usr(s):
        return isinstance(s, str) and re.fullmatch(r"^xt_usr_[0-9A-HJKMNP-TV-Z]{17,}$", s or "") is not None

    def _norm_sn(s):
        return (s or "").strip().lower()

    def _pick_account(acct_id):
        accounts = _load("accounts.json")
        if not isinstance(accounts, list): accounts = []
        if acct_id is not None:
            if not isinstance(acct_id, str) or not acct_id:
                return None
            for a in accounts:
                if a.get("id") == acct_id and a.get("status") == "active":
                    return a
            return None
        # ambient: pick any active account
        for a in accounts:
            if a.get("status") == "active":
                return a
        return None

    # Validation
    if user_id is None and x_user_id is None:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="Either user_id or x_user_id must be provided.")
        return _err("VALIDATION_ERROR", "Either user_id or x_user_id must be provided.", field="user_id")
    if user_id is not None and (not isinstance(user_id, str) or not user_id or not _is_xt_usr(user_id)):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="user_id is malformed.")
        return _err("VALIDATION_ERROR", "user_id is malformed.", field="user_id")
    if x_user_id is not None and (not isinstance(x_user_id, str) or not x_user_id.strip()):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="x_user_id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "x_user_id must be a non-empty string.", field="x_user_id")
    if refresh is not None and not isinstance(refresh, bool):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="refresh must be boolean.")
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")

    users = _load("users.json")
    if not isinstance(users, list): users = []

    by_local = None
    by_x = None

    if user_id is not None:
        for u in users:
            if u.get("id") == user_id:
                by_local = u
                break

    if x_user_id is not None:
        for u in users:
            if u.get("x_id") == x_user_id.strip():
                by_x = u
                break

    # If both provided and both resolve, they must be the same user
    if by_local is not None and by_x is not None and by_local.get("id") != by_x.get("id"):
        # Vendor contract says raise validation error in this case; however audit shows this check was too eager
        # when one of the identifiers is actually not meant to be consistent with current cache.
        # We only raise when both identifiers resolve to different existing rows.
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="user_id and x_user_id refer to different users.", meta={"user_id": user_id, "x_user_id": x_user_id})
        return _err("VALIDATION_ERROR", "user_id and x_user_id refer to different users.", field="x_user_id")

    # Choose resolved user if present
    user = by_local or by_x

    # If not found, "fetch from X and upsert" (offline): create minimal user row using provided identifier
    # Prefer using x_user_id if given; else if only user_id given, cannot infer x_id -> NOT_FOUND
    if user is None:
        if x_user_id is None:
            _reqlog("error", credential_id=account_id, error_code="NOT_FOUND", error_message="User not found.")
            return _err("NOT_FOUND", "User not found.")
        # upsert new user row while enforcing uniqueness on x_id and lower(screen_name)
        # Since we have no upstream data, synthesize a stable screen_name that won't collide if possible.
        new_x = x_user_id.strip()
        # uniqueness on x_id
        for u in users:
            if u.get("x_id") == new_x:
                user = u
                break
        if user is None:
            base_sn = f"user{new_x[-6:]}" if len(new_x) >= 6 else f"user{new_x}"
            sn = base_sn
            taken = {(_norm_sn(u.get("screen_name"))): True for u in users if isinstance(u.get("screen_name"), str)}
            k = 0
            while _norm_sn(sn) in taken:
                k += 1
                sn = f"{base_sn}{k}"
            user = {
                "id": _gen_id("xt_usr_"),
                "x_id": new_x,
                "screen_name": sn,
                "display_name": None,
                "bio": None,
                "location": None,
                "profile_image_url": None,
                "verified_type": "none",
                "protected": False,
                "followers_count": None,
                "following_count": None,
                "statuses_count": None,
                "favourites_count": None,
                "joined_at": None,
                "last_fetched_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            users.append(user)
            _save("users.json", users)
        _reqlog("ok", credential_id=account_id, meta={"source": "upsert_stub", "x_user_id": x_user_id})
