    now_iso = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _reqlog(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _gen_id("xt_req_"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _encode_cursor(offset):
        raw = f"o:{int(offset)}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(c):
        if c is None or c == "":
            return 0
        if not isinstance(c, str):
            return None
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8", "ignore")
            if raw.startswith("o:"):
                return int(raw.split(":", 1)[1])
        except Exception:
            pass
        return 0

    def _pick_active_account(acct_id):
        if not isinstance(acct_id, str) or not acct_id:
            return None
        accounts = _load("accounts.json")
        if not isinstance(accounts, list): accounts = []
        for a in accounts:
            if a.get("id") == acct_id and a.get("status") == "active":
                return a
        return None

    def _norm_sn(s):
        return (s or "").strip().lower()

    # Validate
    if account_id is None or not isinstance(account_id, str) or not account_id:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="account_id is required.")
        return _err("VALIDATION_ERROR", "account_id is required.", field="account_id")
    acct = _pick_active_account(account_id)
    if acct is None:
        _reqlog("error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="No active account context available.")
        return _err("UNAUTHORIZED", "No active account context available.")

    if user_x_id is None and screen_name is None:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="user_x_id or screen_name must be provided.")
        return _err("VALIDATION_ERROR", "Either user_x_id or screen_name must be provided.", field="user_x_id")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="limit out of range.")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
    if refresh is not None and not isinstance(refresh, bool):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="refresh must be boolean.")
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")

    offset = _decode_cursor(cursor)
    if offset is None:
        offset = 0

    users = _load("users.json")
    if not isinstance(users, list): users = []
    rels = _load("user_relationships.json")
    if not isinstance(rels, list): rels = []

    # Resolve target x_id
    target_x = None
    if user_x_id is not None:
        if not isinstance(user_x_id, str) or not user_x_id.strip():
            _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="user_x_id must be non-empty.")
            return _err("VALIDATION_ERROR", "user_x_id must be a non-empty string.", field="user_x_id")
        target_x = user_x_id.strip()
    else:
        if not isinstance(screen_name, str) or not screen_name.strip():
            _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="screen_name must be non-empty.")
            return _err("VALIDATION_ERROR", "screen_name must be a non-empty string.", field="screen_name")
        sn = _norm_sn(screen_name)
        for u in users:
            if _norm_sn(u.get("screen_name")) == sn:
                target_x = u.get("x_id")
                break

    if not target_x:
        _reqlog("error", credential_id=account_id, error_code="NOT_FOUND", error_message="Target user not found.")
        return _err("NOT_FOUND", "Target user not found.")

    # Refresh: offline bump observed
    if refresh is True:
        changed = False
        for e in rels:
            if e.get("relationship_type") == "subscribes" and e.get("from_user_x_id") == target_x and e.get("status") == "active":
                e["observed_at"] = now_iso
                e["updated_at"] = now_iso
                changed = True
        if changed:
            _save("user_relationships.json", rels)

    subs_edges = [e for e in rels if e.get("relationship_type") == "subscribes" and e.get("from_user_x_id") == target_x and e.get("status") == "active"]
    sub_ids = [e.get("to_user_x_id") for e in sorted(subs_edges, key=lambda x: (x.get("observed_at") or "", x.get("id") or "")) if isinstance(e.get("to_user_x_id"), str)]

    total = len(sub_ids)
    page_ids = sub_ids[offset: offset + limit]
    id_set = set(page_ids)
    page_users = [u for u in users if u.get("x_id") in id_set]
    by_x = {u.get("x_id"): u for u in page_users}
    ordered_users = [by_x[x] for x in page_ids if x in by_x]

    next_offset = offset + len(page_ids)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    _reqlog("ok", credential_id=account_id, meta={"target_user_x_id": target_x, "total": total, "cursor_in": cursor})
    return {"users": ordered_users, "meta": {"total": total, "count": len(ordered_users), "has_more": has_more, "next_cursor": next_cursor}}

def post_tweet(account_id, text, reply_to_tweet_x_id=None, quote_tweet_x_id=None, media=None, hashtags=None, mentions=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential=None, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "xt_req_" + "".join(random.choice("0123456789ABCDEFGHJKMNPQRSTVWXYZ") for _ in range(20)),
            "endpoint": "post_tweet",
            "account_id": account_id if isinstance(account_id, str) else None,
            "credential": credential,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if meta is not None:
            row["meta"] = meta
        if error is not None:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    def _is_valid_account_id(s):
        return isinstance(s, str) and re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{17,}$", s) is not None

    # Validate
    if not _is_valid_account_id(account_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Malformed account_id"})
        return _err("VALIDATION_ERROR", "Malformed account_id")
    if not isinstance(text, str) or len(text) < 1 or len(text) > 280:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "text must be a string of length 1–280"})
        return _err("VALIDATION_ERROR", "text must be a string of length 1–280")
    if reply_to_tweet_x_id is not None and (not isinstance(reply_to_tweet_x_id, str) or not reply_to_tweet_x_id.strip()):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "reply_to_tweet_x_id must be a non-empty string"})
        return _err("VALIDATION_ERROR", "reply_to_tweet_x_id must be a non-empty string")
    if quote_tweet_x_id is not None and (not isinstance(quote_tweet_x_id, str) or not quote_tweet_x_id.strip()):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "quote_tweet_x_id must be a non-empty string"})
        return _err("VALIDATION_ERROR", "quote_tweet_x_id must be a non-empty string")
    if reply_to_tweet_x_id is not None and quote_tweet_x_id is not None:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Cannot set both reply_to_tweet_x_id and quote_tweet_x_id"})
        return _err("VALIDATION_ERROR", "Cannot set both reply_to_tweet_x_id and quote_tweet_x_id")
    if media is not None:
        if not isinstance(media, list):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "media must be an array"})
            return _err("VALIDATION_ERROR", "media must be an array")
        for i, item in enumerate(media):
            if not isinstance(item, dict):
                _log("error", error={"code": "VALIDATION_ERROR", "message": f"media[{i}] must be an object"})
                return _err("VALIDATION_ERROR", f"media[{i}] must be an object")
            if "media_id" not in item or not isinstance(item.get("media_id"), str) or not item.get("media_id").strip():
                _log("error", error={"code": "VALIDATION_ERROR", "message": f"media[{i}].media_id is required"})
                return _err("VALIDATION_ERROR", f"media[{i}].media_id is required")
            if "alt_text" in item and item["alt_text"] is not None and not isinstance(item["alt_text"], str):
                _log("error", error={"code": "VALIDATION_ERROR", "message": f"media[{i}].alt_text must be string"})
                return _err("VALIDATION_ERROR", f"media[{i}].alt_text must be string")
            extra_keys = set(item.keys()) - {"media_id", "alt_text"}
            if extra_keys:
                _log("error", error={"code": "VALIDATION_ERROR", "message": f"media[{i}] has unknown fields"})
                return _err("VALIDATION_ERROR", f"media[{i}] has unknown fields")
    if hashtags is not None:
        if not isinstance(hashtags, list) or any((not isinstance(h, str)) for h in hashtags):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "hashtags must be an array of strings"})
            return _err("VALIDATION_ERROR", "hashtags must be an array of strings")
    if mentions is not None:
        if not isinstance(mentions, list) or any((not isinstance(m, str)) for m in mentions):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "mentions must be an array of strings"})
            return _err("VALIDATION_ERROR", "mentions must be an array of strings")

    # Auth: exactly one active account row must be associated -> here by account_id
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        _log("error", credential=None, error={"code": "UNAUTHORIZED", "message": "No active account available for this operation"})
        return _err("UNAUTHORIZED", "No active account available for this operation")

    # X confirmation would happen here; offline server simulates confirmation by writing locally.
    tweets = _load("tweets.json")
    if not isinstance(tweets, list):
        tweets = []
    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    author_xid = acct.get("x_user_id")
    if not isinstance(author_xid, str) or not author_xid:
        _log("error", credential=account_id, error={"code": "UNAUTHORIZED", "message": "Account is missing x_user_id linkage"})
        return _err("UNAUTHORIZED", "Account is missing x_user_id linkage")

    # Ensure referenced author user exists (upsert minimal if missing)
    author_user = next((u for u in users if isinstance(u, dict) and u.get("x_id") == author_xid), None)
    if not author_user:
        # create minimal user row (offline "fetch")
        new_user = {
            "id": "xt_usr_" + "".join(random.choice("0123456789ABCDEFGHJKMNPQRSTVWXYZ") for _ in range(20)),
            "x_id": author_xid,
            "screen_name": acct.get("screen_name") or f"user_{author_xid[-6:]}",
            "display_name": acct.get("display_name"),
            "bio": None,
            "location": None,
            "profile_image_url": None,
            "verified_type": "none",
            "protected": False,
            "followers_count": None,
            "following_count": None,
            "statuses_count": None,
            "favourites_count": None,
            "joined_at": None,
            "last_fetched_at": now,
            "created_at": now,
            "updated_at": now
        }
        # enforce unique(lower(screen_name))
        snl = new_user["screen_name"].lower()
        if any(isinstance(u, dict) and isinstance(u.get("screen_name"), str) and u.get("screen_name").lower() == snl for u in users):
            # adjust to keep unique
            new_user["screen_name"] = f"{new_user['screen_name']}_{author_xid[-4:]}"
        users.append(new_user)
        _save("users.json", users)

    # Generate a tweet x_id (simulate X snowflake-like)
    x_id = "x_tw_" + "".join(random.choice("0123456789") for _ in range(18))

    # Idempotency: if same x_id exists (unlikely), update it
    existing = next((t for t in tweets if isinstance(t, dict) and t.get("x_id") == x_id), None)

    def _new_internal_id():
        return "xt_twt_" + "".join(random.choice("0123456789ABCDEFGHJKMNPQRSTVWXYZ") for _ in range(20))

    tweet_row = {
        "id": existing.get("id") if existing else _new_internal_id(),
        "x_id": x_id,
        "author_user_x_id": author_xid,
        "created_on_x_at": now,
        "text": text,
        "lang": None,
        "conversation_x_id": None,
        "in_reply_to_tweet_x_id": reply_to_tweet_x_id,
        "in_reply_to_user_x_id": None,
        "quote_tweet_x_id": quote_tweet_x_id,
        "hashtags": hashtags if hashtags is not None else None,
        "mentions_user_x_ids": None,
        "media": media if media is not None else None,
        "poll": None,
        "public_metrics": None,
        "status": "visible",
        "deleted_on_x_at": None,
        "source": "posted_via_api",
        "created_at": existing.get("created_at") if existing else now,
        "updated_at": now
    }

    # constraints
    if tweet_row["text"] is not None and len(tweet_row["text"]) > 10000:
        _log("error", credential=account_id, error={"code": "VALIDATION_ERROR", "message": "Tweet text exceeds storage limit"})
        return _err("VALIDATION_ERROR", "Tweet text exceeds storage limit")
    if tweet_row["in_reply_to_tweet_x_id"] is not None and tweet_row["in_reply_to_tweet_x_id"] == tweet_row["x_id"]:
        _log("error", credential=account_id, error={"code": "VALIDATION_ERROR", "message": "in_reply_to_tweet_x_id cannot equal tweet x_id"})
        return _err("VALIDATION_ERROR", "in_reply_to_tweet_x_id cannot equal tweet x_id")

    # Persist tweet
    if existing:
        for i, t in enumerate(tweets):
            if isinstance(t, dict) and t.get("x_id") == x_id:
                tweets[i] = tweet_row
                break
    else:
        tweets.append(tweet_row)
    _save("tweets.json", tweets)

    # Update account last_used
    acct["last_used_at"] = now
    acct["updated_at"] = now
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("id") == account_id:
            accounts[i] = acct
            break
    _save("accounts.json", accounts)

    _log("ok", credential=account_id, meta={"tweet_x_id": x_id})
    return {"data": tweet_row}

def delete_tweet(account_id, tweet_id, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_tweet"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _reqlog(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _gen_id("xt_req_"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(account_id, str) or not account_id:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="account_id must be non-empty.")
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.", field="account_id")
    if not isinstance(tweet_id, str) or not tweet_id:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="tweet_id must be non-empty.")
        return _err("VALIDATION_ERROR", "tweet_id must be a non-empty string.", field="tweet_id")
    if re.fullmatch(r"^[0-9]+$", tweet_id) is None:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="tweet_id must be numeric.")
        return _err("VALIDATION_ERROR", "tweet_id must be a numeric X/Twitter id.", field="tweet_id")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list): accounts = []
    acct = None
    for a in accounts:
        if a.get("id") == account_id and a.get("status") == "active":
            acct = a
            break
    if acct is None:
        _reqlog("error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="No active account context available.")
        return _err("UNAUTHORIZED", "No active account context available.")

    tweets = _load("tweets.json")
    if not isinstance(tweets, list): tweets = []

    tw = None
    for t in tweets:
        if t.get("x_id") == tweet_id:
            tw = t
            break

    if tw is None:
        _reqlog("error", credential_id=account_id, error_code="NOT_FOUND", error_message="Tweet not found.")
        return _err("NOT_FOUND", "Tweet not found.")

    # Idempotent deletion
    if tw.get("status") == "deleted":
        # ensure deleted_on_x_at exists
        if tw.get("deleted_on_x_at") is None:
            tw["deleted_on_x_at"] = now_iso
            tw["updated_at"] = now_iso
            _save("tweets.json", tweets)
        _reqlog("ok", credential_id=account_id, meta={"idempotent": True, "tweet_x_id": tweet_id})
        return {"tweet": tw, "deleted": True}

    # Enforce lifecycle transition visible -> deleted only (idempotent for already deleted handled above)
    if tw.get("status") != "visible":
        _reqlog("error", credential_id=account_id, error_code="INVALID_TRANSITION", error_message="Tweet cannot be deleted from its current status.", meta={"current_status": tw.get("status")})
        return _err("INVALID_TRANSITION", "Tweet cannot be deleted from its current status.", current_status=tw.get("status"))

    tw["status"] = "deleted"
    tw["deleted_on_x_at"] = now_iso
    tw["updated_at"] = now_iso
    _save("tweets.json", tweets)

    # update account last_used_at
    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("accounts.json", accounts)

    _reqlog("ok", credential_id=account_id, meta={"tweet_x_id": tweet_id})
    return {"tweet": tw, "deleted": True}

