def create_poll_tweet(account_id, text, choices, duration_minutes, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
