    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_poll_tweet"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _reqlog(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _gen_id("xt_req_"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _gen_x_id():
        # numeric-ish
        ms = int(time.time() * 1000)
        return str(ms * 1000 + random.randint(0, 999))

    # Validate
    if not isinstance(account_id, str) or not account_id:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="account_id must be non-empty.")
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.", field="account_id")
    if not isinstance(text, str):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="text must be a string.")
        return _err("VALIDATION_ERROR", "text must be a string.", field="text")
    if not isinstance(choices, list):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="choices must be an array.")
        return _err("VALIDATION_ERROR", "choices must be an array.", field="choices")
    # Relaxed: if upstream passed wrong count, do not fabricate success; enforce true business rule.
    if len(choices) < 2 or len(choices) > 4:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="choices must contain between 2 and 4 items.")
        return _err("VALIDATION_ERROR", "choices must contain between 2 and 4 items.", field="choices")
    if not isinstance(duration_minutes, int) or duration_minutes < 1:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="duration_minutes must be >= 1.")
        return _err("VALIDATION_ERROR", "duration_minutes must be >= 1.", field="duration_minutes")

    duration_seconds = duration_minutes * 60
    if duration_seconds < 300 or duration_seconds > 604800:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="Poll duration must be between 300 and 604800 seconds.")
        return _err("VALIDATION_ERROR", "Poll duration must be between 5 minutes and 7 days.", field="duration_minutes")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list): accounts = []
    acct = None
    for a in accounts:
        if a.get("id") == account_id and a.get("status") == "active":
            acct = a
            break
    if acct is None:
        _reqlog("error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="No active account context available.")
        return _err("UNAUTHORIZED", "No active account context available.")

    tweets = _load("tweets.json")
    if not isinstance(tweets, list): tweets = []

    x_id = _gen_x_id()

    # Idempotency if x_id already exists (rare here): update instead of creating new
    existing = None
    for t in tweets:
        if t.get("x_id") == x_id:
            existing = t
            break

    poll_obj = {
        "options": [{"label": str(c)} for c in choices],
        "duration_seconds": duration_seconds,
        "end_time": (now_dt + datetime.timedelta(seconds=duration_seconds)).isoformat() + "Z",
        "totals": None,
    }

    if existing is not None:
        existing["text"] = text
        existing["poll"] = poll_obj
        existing["source"] = "posted_via_api"
        if existing.get("status") != "deleted":
            existing["status"] = "visible"
        existing["updated_at"] = now_iso
        tweet_row = existing
    else:
        tweet_row = {
            "id": _gen_id("xt_twt_"),
            "x_id": x_id,
            "author_user_x_id": acct.get("x_user_id"),
            "created_on_x_at": now_iso,
            "text": text,
            "lang": None,
            "conversation_x_id": None,
            "in_reply_to_tweet_x_id": None,
            "in_reply_to_user_x_id": None,
            "quote_tweet_x_id": None,
            "hashtags": None,
            "mentions_user_x_ids": None,
            "media": None,
            "poll": poll_obj,
            "public_metrics": None,
            "status": "visible",
            "deleted_on_x_at": None,
            "source": "posted_via_api",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tweets.append(tweet_row)

    _save("tweets.json", tweets)

    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("accounts.json", accounts)

    _reqlog("ok", credential_id=account_id, meta={"tweet_x_id": x_id, "poll_options": len(choices), "duration_seconds": duration_seconds})
    return {"tweet": tweet_row}

def vote_on_poll(account_id, tweet_id, choice_index, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return _now_dt().isoformat()

    def _log(endpoint, credential, status, started, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"xt_req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": endpoint,
            "credential": credential,
            "status": status,
            "latency_ms": int((time.time() - started) * 1000),
            "timestamp": _now(),
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return f"{prefix}{int(time.time()*1000)}_{random.randint(100000,999999)}"

    started = time.time()
    endpoint = "vote_on_poll"

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{18,}$", account_id):
        _log(endpoint, account_id if isinstance(account_id, str) else None, "error", started, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
    if not isinstance(tweet_id, str) or not re.match(r"^[0-9]+$", tweet_id):
        _log(endpoint, account_id, "error", started, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "tweet_id is malformed.", field="tweet_id")
    if not isinstance(choice_index, int) or choice_index < 0:
        _log(endpoint, account_id, "error", started, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "choice_index must be an integer >= 0.", field="choice_index")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct or acct.get("status") != "active":
        _log(endpoint, account_id, "error", started, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Account is not active or not found.")

    tweets = _load("tweets.json")
    if not isinstance(tweets, list):
        tweets = []
    engagements = _load("tweet_engagements.json")
    if not isinstance(engagements, list):
        engagements = []

    tw = next((t for t in tweets if isinstance(t, dict) and t.get("x_id") == tweet_id), None)
    if not tw:
        _log(endpoint, account_id, "error", started, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Tweet not found.", tweet_id=tweet_id)

    poll = tw.get("poll")
    if poll is None or not isinstance(poll, dict) or not isinstance(poll.get("options"), list):
        _log(endpoint, account_id, "error", started, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Tweet does not contain a poll.", tweet_id=tweet_id)

    options = poll.get("options") or []
    if choice_index >= len(options):
        _log(endpoint, account_id, "error", started, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "choice_index out of bounds for poll options.", field="choice_index", options_count=len(options))

    # Check poll closed
    end_time = poll.get("end_time")
    if isinstance(end_time, str):
        try:
            # Accept ISO strings with timezone
            end_dt = datetime.datetime.fromisoformat(end_time)
            if end_dt.tzinfo is None:
                end_dt = end_dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            end_dt = None
        if end_dt is not None and _now_dt() >= end_dt:
            _log(endpoint, account_id, "error", started, {"code": "CONFLICT"})
            return _err("CONFLICT", "Poll is closed.")

    now = _now()

    # Upsert engagement (unique(account_id, tweet_x_id, engagement_type))
    e = next((x for x in engagements if isinstance(x, dict)
              and x.get("account_id") == account_id
              and x.get("tweet_x_id") == tweet_id
              and x.get("engagement_type") == "poll_vote"), None)

    previous_choice = None
    if e and e.get("status") == "active":
        previous_choice = e.get("poll_choice_index")

    # Apply vote locally (simulate X success). If changing vote, adjust counts.
    # Keep counts non-negative.
    def _opt_votes(i):
        v = options[i].get("votes")
        return v if isinstance(v, int) and v >= 0 else 0

    if previous_choice is not None and isinstance(previous_choice, int) and 0 <= previous_choice < len(options):
        if previous_choice != choice_index:
            pv = _opt_votes(previous_choice)
            options[previous_choice]["votes"] = max(0, pv - 1)

    cv = _opt_votes(choice_index)
    options[choice_index]["votes"] = cv + 1

    total = 0
    for i in range(len(options)):
        total += _opt_votes(i)
    poll["total_votes"] = total
    poll["options"] = options
    tw["poll"] = poll
    tw["updated_at"] = now

    if e:
        # lifecycle transition removed->active allowed, active->removed allowed
        e["status"] = "active"
        e["poll_choice_index"] = choice_index
        e["removed_at"] = None
        e["updated_at"] = now
        # keep engaged_at original if exists
        if not e.get("engaged_at"):
            e["engaged_at"] = now
    else:
        e = {
            "id": _gen_id("xt_eng_"),
            "account_id": account_id,
            "tweet_x_id": tweet_id,
            "engagement_type": "poll_vote",
            "status": "active",
            "poll_choice_index": choice_index,
            "x_engagement_id": None,
            "engaged_at": now,
            "removed_at": None,
            "created_at": now,
            "updated_at": now,
        }
        engagements.append(e)

    acct["last_used_at"] = now
    acct["updated_at"] = now

    _save("tweets.json", tweets)
    _save("tweet_engagements.json", engagements)
    _save("accounts.json", accounts)

    _log(endpoint, account_id, "ok", started)
    return {
        "tweet_id": tweet_id,
        "poll": poll,
        "engagement": e,
    }

