        return _err("CONFLICT", "Cannot favorite a deleted or tombstoned tweet.", tweet_status=tw.get("status"))

    engagements = _load("tweet_engagements.json")
    if not isinstance(engagements, list): engagements = []

    row = None
    for e in engagements:
        if e.get("account_id") == account_id and e.get("tweet_x_id") == tweet_id and e.get("engagement_type") == "favorite":
            row = e
