    row["removed_at"] = None
    row["engaged_at"] = row.get("engaged_at") or now_iso
    row["updated_at"] = now_iso
    _save("tweet_engagements.json", engagements)

    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("accounts.json", accounts)

    _reqlog("ok", credential_id=account_id, meta={"tweet_x_id": tweet_id, "idempotent": False})
