def unfavorite_tweet(account_id, tweet_id, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, error_code=None, error_message=None, meta=None):
        row = {
            "id": "xt_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs = _load("request_logs.json")
        logs.append(row)
        _save("request_logs.json", logs)

    def _is_active_account(acct):
        return isinstance(acct, dict) and acct.get("status") == "active"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _enforce_rate_limit(acct):
        state = acct.get("rate_limit_state") if isinstance(acct.get("rate_limit_state"), dict) else {}
        eng = state.get("engagement_write") if isinstance(state.get("engagement_write"), dict) else {}
        window_s = eng.get("window_seconds", 900)
        limit = eng.get("limit", 50)
        reset_at = eng.get("reset_at")
        remaining = eng.get("remaining")

        now_dt = datetime.datetime.utcnow()
        reset_dt = _parse_dt(reset_at) if isinstance(reset_at, str) else None
        if reset_dt is None or reset_dt <= now_dt or remaining is None or not isinstance(remaining, int):
            reset_dt = now_dt + datetime.timedelta(seconds=int(window_s))
            remaining = int(limit)

        if remaining <= 0:
            eng["window_seconds"] = int(window_s)
            eng["limit"] = int(limit)
            eng["reset_at"] = reset_dt.replace(microsecond=0).isoformat() + "Z"
            eng["remaining"] = int(remaining)
            state["engagement_write"] = eng
            acct["rate_limit_state"] = state
            return False, reset_dt

        remaining -= 1
        eng["window_seconds"] = int(window_s)
        eng["limit"] = int(limit)
        eng["reset_at"] = reset_dt.replace(microsecond=0).isoformat() + "Z"
        eng["remaining"] = int(remaining)
        state["engagement_write"] = eng
        acct["rate_limit_state"] = state
        return True, reset_dt

    endpoint = "unfavorite_tweet"

    if not isinstance(account_id, str) or not re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{18,}$", account_id):
        _log(endpoint, "error", credential_id=None, error_code="VALIDATION_ERROR", error_message="Invalid account_id.")
        return _err("VALIDATION_ERROR", "Invalid account_id.", field="account_id")
    if not isinstance(tweet_id, str) or not re.match(r"^[0-9]+$", tweet_id):
        _log(endpoint, "error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="Invalid tweet_id.")
        return _err("VALIDATION_ERROR", "Invalid tweet_id.", field="tweet_id")

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not _is_active_account(acct):
        _log(endpoint, "error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="No active account context for account_id.")
        return _err("UNAUTHORIZED", "No active account context for account_id.", account_id=account_id)

    ok, reset_dt = _enforce_rate_limit(acct)
    if not ok:
        acct["last_used_at"] = now
        acct["updated_at"] = now
        _save("accounts.json", accounts)
        _log(endpoint, "error", credential_id=account_id, error_code="RATE_LIMIT", error_message="Rate limit exceeded.", meta={"reset_at": reset_dt.replace(microsecond=0).isoformat() + "Z"})
        return _err("RATE_LIMIT", "Rate limit exceeded.", reset_at=reset_dt.replace(microsecond=0).isoformat() + "Z")

    tweets = _load("tweets.json")
    tw = next((t for t in tweets if t.get("x_id") == tweet_id), None)
    if tw is None:
        acct["last_used_at"] = now
        acct["updated_at"] = now
        _save("accounts.json", accounts)
        _log(endpoint, "error", credential_id=account_id, error_code="NOT_FOUND", error_message="Tweet not found.")
        return _err("NOT_FOUND", "Tweet not found.", tweet_id=tweet_id)

    engagements = _load("tweet_engagements.json")
    existing = next((e for e in engagements
                     if e.get("account_id") == account_id and e.get("tweet_x_id") == tweet_id and e.get("engagement_type") == "favorite"), None)

    if not existing:
        acct["last_used_at"] = now
        acct["updated_at"] = now
        _save("accounts.json", accounts)
        _log(endpoint, "error", credential_id=account_id, error_code="CONFLICT", error_message="No existing favorite to remove.")
        return _err("CONFLICT", "No existing favorite to remove.", tweet_id=tweet_id)

    # Idempotent toggle to removed
    if existing.get("status") == "removed":
        acct["last_used_at"] = now
        acct["updated_at"] = now
        _save("accounts.json", accounts)
        _log(endpoint, "ok", credential_id=account_id, meta={"idempotent": True})
        return {
            "tweet_id": tweet_id,
            "account_id": account_id,
            "favorited": False,
            "favorite": existing
        }

    if existing.get("status") != "active":
        acct["last_used_at"] = now
        acct["updated_at"] = now
        _save("accounts.json", accounts)
        _log(endpoint, "error", credential_id=account_id, error_code="INVALID_TRANSITION", error_message="Illegal engagement status transition.")
        return _err("INVALID_TRANSITION", "Illegal engagement status transition.", from_status=existing.get("status"), to_status="removed")

    existing["status"] = "removed"
    existing["removed_at"] = now
    existing["updated_at"] = now

    acct["last_used_at"] = now
    acct["updated_at"] = now
    _save("tweet_engagements.json", engagements)
    _save("accounts.json", accounts)

    _log(endpoint, "ok", credential_id=account_id, meta={"idempotent": False})
    return {
        "tweet_id": tweet_id,
        "account_id": account_id,
        "favorited": False,
        "favorite": existing
    }

