def delete_all_bookmarks(account_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _reqlog(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "xt_req_" + uuid.uuid4().hex,
            "endpoint": "delete_all_bookmarks",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    # Accept either vendor pattern (^xt_acct_01H...) or datastore pattern (^xt_acct_... base32)
    if not isinstance(account_id, str):
        _reqlog("error", credential_id=None, error_code="VALIDATION_ERROR", error_message="account_id must be a string.", meta={"field": "account_id"})
        return _err("VALIDATION_ERROR", "account_id must be a string.", field="account_id")
    if not (re.match(r"^xt_acct_01H[0-9A-Z]{15,}$", account_id) or re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{18,}$", account_id)):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="account_id is malformed.", meta={"field": "account_id"})
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct or acct.get("status") != "active":
        _reqlog("error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="No active authenticated account context for this request.")
        return _err("UNAUTHORIZED", "No active authenticated account context for this request.")

    # Enforce quota by counting active bookmarks; allow clearing but prevent excessive frequency (5/min)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    since = now_dt - datetime.timedelta(seconds=60)
    cnt = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != "delete_all_bookmarks":
            continue
        if r.get("credential_id") != account_id:
            continue
        ts = _parse_dt(r.get("created_at") or r.get("timestamp"))
        if ts and ts >= since:
            cnt += 1
    if cnt >= 5:
        _reqlog("error", credential_id=account_id, error_code="QUOTA_EXCEEDED", error_message="Too many delete_all_bookmarks operations in a short period.")
        return _err("QUOTA_EXCEEDED", "Too many delete_all_bookmarks operations in a short period.", window_seconds=60, limit=5)

    engagements = _load("tweet_engagements.json")
    if not isinstance(engagements, list):
        engagements = []

    affected = 0
    for e in engagements:
        if not isinstance(e, dict):
            continue
        if e.get("account_id") == account_id and e.get("engagement_type") == "bookmark" and e.get("status") == "active":
            e["status"] = "removed"
            e["removed_at"] = now_iso
            e["updated_at"] = now_iso
            affected += 1

    if affected == 0:
        # No success without effect: this mutation would have no effect
        _reqlog("error", credential_id=account_id, error_code="NOT_FOUND", error_message="No active bookmarks to delete.")
        return _err("NOT_FOUND", "No active bookmarks to delete.")

    _save("tweet_engagements.json", engagements)
    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("accounts.json", accounts)

    _reqlog("success", credential_id=account_id, meta={"removed_count": affected})
    return {"account_id": account_id, "removed_count": affected}

def get_timeline(account_id, limit=None, cursor=None, refresh=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _reqlog(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "xt_req_" + uuid.uuid4().hex,
            "endpoint": "get_timeline",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    # accept vendor pattern or datastore pattern
    if not isinstance(account_id, str) or not (re.match(r"^xt_acct_01H[0-9A-Z]{15,}$", account_id) or re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{18,}$", account_id)):
        _reqlog("error", credential_id=account_id if isinstance(account_id, str) else None,
                error_code="VALIDATION_ERROR", error_message="account_id is malformed.", meta={"field": "account_id"})
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 200.", meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="cursor must be a string.", meta={"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    if refresh is not None and not isinstance(refresh, bool):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="refresh must be a boolean.", meta={"field": "refresh"})
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")
    if refresh is None:
        refresh = False

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct or acct.get("status") != "active":
        _reqlog("error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="No active authenticated account context for this request.")
        return _err("UNAUTHORIZED", "No active authenticated account context for this request.")

    # Rate limit via request_logs: 60/min
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    since = now_dt - datetime.timedelta(seconds=60)
    cnt = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != "get_timeline":
            continue
        if r.get("credential_id") != account_id:
            continue
        ts = _parse_dt(r.get("created_at") or r.get("timestamp"))
        if ts and ts >= since:
            cnt += 1
    if cnt >= 60:
        _reqlog("error", credential_id=account_id, error_code="RATE_LIMIT", error_message="Too many requests for this endpoint.")
        return _err("RATE_LIMIT", "Too many requests for this endpoint.", window_seconds=60, limit=60)

    feeds = _load("feeds_and_searches.json")
    if not isinstance(feeds, list):
        feeds = []
    tweets = _load("tweets.json")
    if not isinstance(tweets, list):
        tweets = []

    # Cache reuse if refresh == False and a fresh, unexpired entry exists for same (account_id, cursor)
    def _is_fresh_feed(f):
        if not isinstance(f, dict):
            return False
        if f.get("account_id") != account_id:
            return False
        if f.get("kind") != "home_timeline_for_you":
            return False
        if (f.get("cursor") or None) != (cursor or None):
            return False
        if f.get("status") != "fresh":
            return False
        exp = _parse_dt(f.get("expires_at")) if isinstance(f.get("expires_at"), str) else None
        if exp is None:
            return True
        return exp > now_dt

    chosen = None
    if not refresh:
        for f in reversed(feeds):
            if _is_fresh_feed(f):
                chosen = f
                break

    if chosen is None:
        # "Fetch from X" offline: create a fresh feed snapshot from existing tweets
        # Use newest tweets by created_on_x_at/created_at
        def _tweet_sort_key(t):
            if not isinstance(t, dict):
                return datetime.datetime.min
            dtv = _parse_dt(t.get("created_on_x_at")) or _parse_dt(t.get("created_at")) or datetime.datetime.min
            return dtv
        ordered = sorted([t for t in tweets if isinstance(t, dict) and isinstance(t.get("x_id"), str)], key=_tweet_sort_key, reverse=True)
        start = 0
        if cursor:
            # cursor format: "o:<offset>"
            m = re.match(r"^o:(\d+)$", cursor)
            if not m:
                _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="Invalid cursor.", meta={"field": "cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            start = int(m.group(1))

        page = ordered[start:start + limit]
        ids = [t["x_id"] for t in page]
        next_cursor = None
        if start + limit < len(ordered):
            next_cursor = f"o:{start + limit}"

        feed_row = {
            "id": "xt_feed_" + uuid.uuid4().hex[:26],
            "account_id": account_id,
            "kind": "home_timeline_for_you",
            "subject_user_x_id": None,
            "query": None,
            "cursor": cursor,
            "result_tweet_x_ids": ids,
            "result_topics": None,
            "response_meta": {"next_cursor": next_cursor, "partial": False},
            "status": "fresh",
            "fetched_at": now_iso,
            "expires_at": (now_dt + datetime.timedelta(minutes=5)).isoformat() + "Z",
            "error": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        feeds.append(feed_row)
        _save("feeds_and_searches.json", feeds)
        chosen = feed_row
    else:
        ids = chosen.get("result_tweet_x_ids") or []
        next_cursor = (chosen.get("response_meta") or {}).get("next_cursor")

    idset = set(chosen.get("result_tweet_x_ids") or [])
    by_id = {t.get("x_id"): t for t in tweets if isinstance(t, dict) and t.get("x_id") in idset}
    ordered_tweets = [by_id.get(x) for x in (chosen.get("result_tweet_x_ids") or []) if x in by_id]

    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("accounts.json", accounts)

    _reqlog("success", credential_id=account_id, meta={"returned": len(ordered_tweets), "next_cursor": (chosen.get("response_meta") or {}).get("next_cursor")})
    return {
        "tweets": ordered_tweets,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": (chosen.get("response_meta") or {}).get("next_cursor"),
        "has_more": (chosen.get("response_meta") or {}).get("next_cursor") is not None,
