            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    if not isinstance(account_id, str) or not (re.match(r"^xt_acct_01H[0-9A-Z]{15,}$", account_id) or re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{18,}$", account_id)):
        _reqlog("error", credential_id=account_id if isinstance(account_id, str) else None,
                error_code="VALIDATION_ERROR", error_message="account_id is malformed.", meta={"field": "account_id"})
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 200.", meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="cursor must be a string.", meta={"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    if refresh is not None and not isinstance(refresh, bool):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="refresh must be a boolean.", meta={"field": "refresh"})
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")
    if refresh is None:
        refresh = False

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct or acct.get("status") != "active":
        _reqlog("error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="No active authenticated account context for this request.")
        return _err("UNAUTHORIZED", "No active authenticated account context for this request.")

    # Rate limit: 60/min
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    since = now_dt - datetime.timedelta(seconds=60)
    cnt = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != "get_latest_timeline":
            continue
        if r.get("credential_id") != account_id:
            continue
        ts = _parse_dt(r.get("created_at") or r.get("timestamp"))
        if ts and ts >= since:
            cnt += 1
    if cnt >= 60:
        _reqlog("error", credential_id=account_id, error_code="RATE_LIMIT", error_message="Too many requests for this endpoint.")
        return _err("RATE_LIMIT", "Too many requests for this endpoint.", window_seconds=60, limit=60)

    feeds = _load("feeds_and_searches.json")
    if not isinstance(feeds, list):
        feeds = []
    tweets = _load("tweets.json")
    if not isinstance(tweets, list):
        tweets = []

    def _is_fresh_feed(f):
        if not isinstance(f, dict):
            return False
        if f.get("account_id") != account_id:
            return False
        if f.get("kind") != "home_timeline_following":
            return False
        if (f.get("cursor") or None) != (cursor or None):
            return False
        if f.get("status") != "fresh":
            return False
        exp = _parse_dt(f.get("expires_at")) if isinstance(f.get("expires_at"), str) else None
        if exp is None:
            return True
        return exp > now_dt

    chosen = None
    if not refresh:
        for f in reversed(feeds):
            if _is_fresh_feed(f):
                chosen = f
                break

    if chosen is None:
        # Offline "Following" timeline: just same as timeline but separate cache kind
        def _tweet_sort_key(t):
            dtv = _parse_dt(t.get("created_on_x_at")) or _parse_dt(t.get("created_at")) or datetime.datetime.min
            return dtv
        ordered = sorted([t for t in tweets if isinstance(t, dict) and isinstance(t.get("x_id"), str)], key=_tweet_sort_key, reverse=True)
        start = 0
        if cursor:
            m = re.match(r"^o:(\d+)$", cursor)
            if not m:
                _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="Invalid cursor.", meta={"field": "cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            start = int(m.group(1))

        page = ordered[start:start + limit]
        ids = [t["x_id"] for t in page]
        next_cursor = None
        if start + limit < len(ordered):
            next_cursor = f"o:{start + limit}"

        feed_row = {
            "id": "xt_feed_" + uuid.uuid4().hex[:26],
            "account_id": account_id,
            "kind": "home_timeline_following",
            "subject_user_x_id": None,
            "query": None,
            "cursor": cursor,
            "result_tweet_x_ids": ids,
            "result_topics": None,
            "response_meta": {"next_cursor": next_cursor, "partial": False},
            "status": "fresh",
            "fetched_at": now_iso,
            "expires_at": (now_dt + datetime.timedelta(minutes=5)).isoformat() + "Z",
            "error": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        feeds.append(feed_row)
        _save("feeds_and_searches.json", feeds)
        chosen = feed_row

    idset = set(chosen.get("result_tweet_x_ids") or [])
    by_id = {t.get("x_id"): t for t in tweets if isinstance(t, dict) and t.get("x_id") in idset}
    ordered_tweets = [by_id.get(x) for x in (chosen.get("result_tweet_x_ids") or []) if x in by_id]

    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("accounts.json", accounts)

    _reqlog("success", credential_id=account_id, meta={"returned": len(ordered_tweets), "next_cursor": (chosen.get("response_meta") or {}).get("next_cursor")})
    return {
        "tweets": ordered_tweets,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": (chosen.get("response_meta") or {}).get("next_cursor"),
        "has_more": (chosen.get("response_meta") or {}).get("next_cursor") is not None,
        "feed": chosen,
    }

def search_twitter(account_id, query, limit=None, cursor=None, refresh=None, **_extra):
    import json, os, datetime, time, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"
    endpoint = "search_twitter"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _reqlog(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _gen_id("xt_req_"),
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "meta": meta or {},
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso,
            }
        )
        _save("request_logs.json", logs)

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("o:"):
                return int(raw.split(":", 1)[1])
            return None
        except Exception:
            return None

    def _encode_cursor(offset):
        raw = f"o:{int(offset)}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _expires_at(minutes):
        return (now_dt + datetime.timedelta(minutes=minutes)).isoformat() + "Z"

    # Validate
    if not isinstance(account_id, str) or not account_id:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="account_id must be non-empty string.")
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.", field="account_id")

    if not isinstance(query, str) or not query.strip():
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="query must be non-empty string.")
        return _err("VALIDATION_ERROR", "query must be a non-empty string.", field="query")
    query = query.strip()

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="limit must be integer.")
        return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
    if limit < 1 or limit > 200:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="limit out of range.")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")

    offset = _decode_cursor(cursor)
    if cursor is not None and offset is None:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="cursor is malformed.")
        return _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")

    if refresh is not None and not isinstance(refresh, bool):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="refresh must be boolean.")
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id and a.get("status") == "active":
            acct = a
            break
    if not acct:
        _reqlog("error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="No active account context.")
        return _err("UNAUTHORIZED", "No active account context available for this operation.", field="account_id")

    feeds = _load("feeds_and_searches.json")
    if not isinstance(feeds, list):
        feeds = []

    # Cache TTL: 10 minutes for identical (account_id, query, cursor)
    ttl_minutes = 10
    if refresh is not True:
        for f in reversed(feeds):
            if not isinstance(f, dict):
                continue
            if f.get("account_id") != account_id:
                continue
            if f.get("kind") != "search":
                continue
            if f.get("query") != query:
                continue
            if (f.get("cursor") or None) != (cursor or None):
                continue
            if f.get("status") != "fresh":
                continue
            exp = _parse_dt(f.get("expires_at"))
            if exp is not None and exp >= now_dt:
                tweet_ids = f.get("result_tweet_x_ids") if isinstance(f.get("result_tweet_x_ids"), list) else []
                # page within cached list
                total = len(tweet_ids)
                start = int(offset or 0)
                end = min(start + limit, total)
                page_ids = tweet_ids[start:end]
                has_more = end < total
                next_cursor = _encode_cursor(end) if has_more else None

                tweets = _load("tweets.json")
                if not isinstance(tweets, list):
                    tweets = []
                by_xid = {t.get("x_id"): t for t in tweets if isinstance(t, dict) and isinstance(t.get("x_id"), str)}
                page_tweets = [by_xid[x] for x in page_ids if x in by_xid]

                for i, a in enumerate(accounts):
                    if isinstance(a, dict) and a.get("id") == account_id:
                        a["last_used_at"] = now_iso
                        a["updated_at"] = now_iso
                        accounts[i] = a
                        _save("accounts.json", accounts)
                        break

                _reqlog("ok", credential_id=account_id, meta={"cached": True, "feed_id": f.get("id")})
                return {"tweets": page_tweets, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}, "feed": f}

    # Offline "fetch": build results from locally stored tweets whose text contains query (case-insensitive)
    tweets = _load("tweets.json")
    if not isinstance(tweets, list):
        tweets = []
    ql = query.lower()
    matched = []
    for t in tweets:
        if not isinstance(t, dict):
            continue
        txt = t.get("text")
        if isinstance(txt, str) and ql in txt.lower():
            matched.append(t)

    # Sort by created_on_x_at desc then x_id desc
    def _key(t):
        dt = _parse_dt(t.get("created_on_x_at")) or datetime.datetime(1970, 1, 1)
        return (dt, str(t.get("x_id") or ""))

    matched.sort(key=_key, reverse=True)
    result_ids = [t.get("x_id") for t in matched if isinstance(t.get("x_id"), str)]

    # Create feed row
    feed_row = {
        "id": _gen_id("xt_feed_"),
        "account_id": account_id,
        "kind": "search",
        "subject_user_x_id": None,
        "query": query,
        "cursor": cursor,
        "result_tweet_x_ids": result_ids,
        "result_topics": None,
        "response_meta": {"next_cursor": None, "partial": False, "source": "local_search"},
        "status": "fresh",
        "fetched_at": now_iso,
        "expires_at": _expires_at(ttl_minutes),
        "error": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    feeds.append(feed_row)
    _save("feeds_and_searches.json", feeds)

    # Page
    total = len(result_ids)
    start = int(offset or 0)
    end = min(start + limit, total)
    page_tweets = matched[start:end]
    has_more = end < total
    next_cursor = _encode_cursor(end) if has_more else None

    # Update account last_used_at
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("id") == account_id:
            a["last_used_at"] = now_iso
            a["updated_at"] = now_iso
            accounts[i] = a
            _save("accounts.json", accounts)
            break

    _reqlog("ok", credential_id=account_id, meta={"cached": False, "feed_id": feed_row["id"], "total": total})
    return {"tweets": page_tweets, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}, "feed": feed_row}

