            for h in hs:
                if isinstance(h, str) and h:
                    key = h if h.startswith("#") else "#" + h
                    counts[key] = counts.get(key, 0) + 1
        topics = [{"name": k, "tweet_count": v} for k, v in sorted(counts.items(), key=lambda kv: kv[1], reverse=True)]
