            "error": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        feeds.append(feed_row)
        _save("feeds_and_searches.json", feeds)
        cached = feed_row

    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("accounts.json", accounts)

    _reqlog("success", credential_id=account_id, meta={"returned": len(cached.get("result_topics") or []), "next_cursor": (cached.get("response_meta") or {}).get("next_cursor")})
    return {
        "topics": cached.get("result_topics") or [],
        "limit": limit,
        "cursor": cursor,
        "next_cursor": (cached.get("response_meta") or {}).get("next_cursor"),
        "has_more": (cached.get("response_meta") or {}).get("next_cursor") is not None,
        "feed": cached,
    }

def get_highlights_tweets(account_id, user_x_id, limit=None, cursor=None, refresh=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _reqlog(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "xt_req_" + uuid.uuid4().hex,
            "endpoint": "get_highlights_tweets",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    if not isinstance(account_id, str) or not (re.match(r"^xt_acct_01H[0-9A-Z]{15,}$", account_id) or re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{18,}$", account_id)):
        _reqlog("error", credential_id=account_id if isinstance(account_id, str) else None,
                error_code="VALIDATION_ERROR", error_message="account_id is malformed.", meta={"field": "account_id"})
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
    if not isinstance(user_x_id, str) or len(user_x_id) < 1:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="user_x_id is required.", meta={"field": "user_x_id"})
        return _err("VALIDATION_ERROR", "user_x_id is required.", field="user_x_id")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 200.", meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="cursor must be a string.", meta={"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    if refresh is not None and not isinstance(refresh, bool):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="refresh must be a boolean.", meta={"field": "refresh"})
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")
    if refresh is None:
        refresh = False

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct or acct.get("status") != "active":
        _reqlog("error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="No active authenticated account context for this request.")
        return _err("UNAUTHORIZED", "No active authenticated account context for this request.")

    feeds = _load("feeds_and_searches.json")
    if not isinstance(feeds, list):
        feeds = []
    tweets = _load("tweets.json")
    if not isinstance(tweets, list):
        tweets = []

    def _fresh_cached():
        for f in reversed(feeds):
            if not isinstance(f, dict):
                continue
            if f.get("account_id") != account_id or f.get("kind") != "highlights":
                continue
            if f.get("subject_user_x_id") != user_x_id:
                continue
            if (f.get("cursor") or None) != (cursor or None):
                continue
            if f.get("status") != "fresh":
                continue
            exp = _parse_dt(f.get("expires_at")) if isinstance(f.get("expires_at"), str) else None
            if exp is None or exp > now_dt:
                return f
        return None

    chosen = None if refresh else _fresh_cached()

    if chosen is None:
        # Offline highlight synthesis: latest tweets by user as "highlights"
        def _tweet_sort_key(t):
            return _parse_dt(t.get("created_on_x_at")) or _parse_dt(t.get("created_at")) or datetime.datetime.min
        user_tweets = [t for t in tweets if isinstance(t, dict) and t.get("author_user_x_id") == user_x_id and isinstance(t.get("x_id"), str)]
        user_tweets.sort(key=_tweet_sort_key, reverse=True)

        start = 0
        if cursor:
            m = re.match(r"^o:(\d+)$", cursor)
            if not m:
                _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="Invalid cursor.", meta={"field": "cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            start = int(m.group(1))

        page = user_tweets[start:start + limit]
        ids = [t["x_id"] for t in page]
        next_cursor = f"o:{start + limit}" if start + limit < len(user_tweets) else None

        chosen = {
            "id": "xt_feed_" + uuid.uuid4().hex[:26],
            "account_id": account_id,
            "kind": "highlights",
            "subject_user_x_id": user_x_id,
            "query": None,
            "cursor": cursor,
            "result_tweet_x_ids": ids,
            "result_topics": None,
            "response_meta": {"next_cursor": next_cursor, "partial": False},
            "status": "fresh",
            "fetched_at": now_iso,
            "expires_at": (now_dt + datetime.timedelta(minutes=10)).isoformat() + "Z",
            "error": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        feeds.append(chosen)
        _save("feeds_and_searches.json", feeds)

    idset = set(chosen.get("result_tweet_x_ids") or [])
    by_id = {t.get("x_id"): t for t in tweets if isinstance(t, dict) and t.get("x_id") in idset}
    ordered_tweets = [by_id.get(x) for x in (chosen.get("result_tweet_x_ids") or []) if x in by_id]

    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("accounts.json", accounts)

    _reqlog("success", credential_id=account_id, meta={"returned": len(ordered_tweets), "next_cursor": (chosen.get("response_meta") or {}).get("next_cursor")})
    return {
        "tweets": ordered_tweets,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": (chosen.get("response_meta") or {}).get("next_cursor"),
        "has_more": (chosen.get("response_meta") or {}).get("next_cursor") is not None,
        "feed": chosen,
    }

def get_user_mentions(account_id, user_x_id, limit=None, cursor=None, refresh=None, **_extra):
    import json, os, datetime, time, re, base64, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"
    endpoint = "get_user_mentions"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str):
            return None
        if re.fullmatch(r"\d+", c):
            return int(c)
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            if raw.startswith("o:") and raw[2:].isdigit():
                return int(raw[2:])
        except Exception:
            return None
        return None

    def _make_cursor(offset):
        raw = f"o:{offset}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _reqlog(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("xt_req_"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(credential_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        since = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if credential_id and r.get("credential_id") != credential_id:
                continue
            ts = _parse_dt(r.get("created_at") or r.get("timestamp"))
            if ts and ts >= since:
                cnt += 1
        if credential_id and cnt >= 180:
            return _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=60, limit=180)
        return None

    # Validate (relax account id pattern to match actual datastore ids)
    if not isinstance(account_id, str) or not re.fullmatch(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{17,}$", account_id):
        _reqlog("error", credential_id=account_id if isinstance(account_id, str) else None, error_code="VALIDATION_ERROR", error_message="account_id is malformed.")
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
    if not isinstance(user_x_id, str) or len(user_x_id) < 1:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="user_x_id is required.")
        return _err("VALIDATION_ERROR", "user_x_id is required.", field="user_x_id")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="limit out of range.")
        return _err("VALIDATION_ERROR", "limit out of range.", field="limit")
    if refresh is not None and not isinstance(refresh, bool):
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="refresh must be boolean.")
        return _err("VALIDATION_ERROR", "refresh must be boolean.", field="refresh")

    offset = _parse_cursor(cursor)
    if offset is None:
        _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="cursor is invalid.")
        return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    rl = _rate_limit_check(account_id)
    if rl:
        _reqlog("error", credential_id=account_id, error_code=rl["error"]["code"], error_message=rl["error"]["message"])
        return rl

    accounts = _load("accounts.json")
    tweets = _load("tweets.json")
    users = _load("users.json")
    feeds = _load("feeds_and_searches.json")
    if not isinstance(accounts, list): accounts = []
    if not isinstance(tweets, list): tweets = []
    if not isinstance(users, list): users = []
    if not isinstance(feeds, list): feeds = []

    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if acct is None:
        _reqlog("error", credential_id=account_id, error_code="NOT_FOUND", error_message="Account not found.")
        return _err("NOT_FOUND", "Account not found.", field="account_id")
    if acct.get("status") != "active":
        _reqlog("error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="Account context is not active.")
        return _err("UNAUTHORIZED", "Account context is not active.", field="account_id")

    # Try serve from cached feeds unless refresh=True
    matching = []
    if refresh is not True:
        for f in feeds:
            if not isinstance(f, dict):
                continue
            if f.get("kind") != "mentions":
                continue
            if f.get("account_id") != account_id:
                continue
            if f.get("subject_user_x_id") != user_x_id:
                continue
            if f.get("status") != "fresh":
                continue
            matching.append(f)
        # pick latest fetched_at
        def _fetched_key(r):
            dt = _parse_dt(r.get("fetched_at"))
            return dt or datetime.datetime.min
        matching.sort(key=_fetched_key, reverse=True)

    if matching:
        feed = matching[0]
        ids = feed.get("result_tweet_x_ids") if isinstance(feed.get("result_tweet_x_ids"), list) else []
        total = len(ids)
        page_ids = ids[offset: offset + limit]
        next_offset = offset + len(page_ids)
        has_more = next_offset < total
        next_cursor = _make_cursor(next_offset) if has_more else None
        result_tweets = [t for t in tweets if isinstance(t, dict) and t.get("x_id") in set(page_ids)]
        # preserve order
        tw_by_id = {t.get("x_id"): t for t in result_tweets}
        ordered = [tw_by_id[i] for i in page_ids if i in tw_by_id]
        acct["last_used_at"] = now_iso
        acct["updated_at"] = now_iso
        _save("accounts.json", accounts)
        _reqlog("ok", credential_id=account_id, meta={"cached": True, "total": total, "has_more": has_more})
        return {"data": ordered, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

    # Build mentions list from local tweets mentioning user_x_id
    mention_ids = []
    for t in tweets:
        if not isinstance(t, dict):
            continue
        if t.get("status") == "deleted":
            continue
        mx = t.get("mentions_user_x_ids")
        if isinstance(mx, list) and user_x_id in mx and isinstance(t.get("x_id"), str):
            mention_ids.append(t.get("x_id"))

    # deterministic
    def _sort_key(xid):
        try:
            return int(xid)
        except Exception:
            return xid
    mention_ids = sorted(set(mention_ids), key=_sort_key, reverse=True)

    # Create feeds_and_searches row per business rule
    feed_row = {
        "id": _gen_id("xt_feed_"),
        "account_id": account_id,
        "kind": "mentions",
        "subject_user_x_id": user_x_id,
        "query": None,
        "cursor": cursor if isinstance(cursor, str) else None,
        "result_tweet_x_ids": mention_ids,
        "result_topics": None,
        "response_meta": {"partial": False, "next_cursor": None},
        "status": "fresh",
        "fetched_at": now_iso,
        "expires_at": (now_dt + datetime.timedelta(minutes=5)).isoformat() + "Z",
        "error": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    feeds.append(feed_row)
    _save("feeds_and_searches.json", feeds)

    total = len(mention_ids)
    page_ids = mention_ids[offset: offset + limit]
    next_offset = offset + len(page_ids)
    has_more = next_offset < total
    next_cursor = _make_cursor(next_offset) if has_more else None
    result_tweets = [t for t in tweets if isinstance(t, dict) and t.get("x_id") in set(page_ids)]
    tw_by_id = {t.get("x_id"): t for t in result_tweets}
    ordered = [tw_by_id[i] for i in page_ids if i in tw_by_id]

    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("accounts.json", accounts)

    _reqlog("ok", credential_id=account_id, meta={"cached": False, "total": total, "has_more": has_more})
    return {"data": ordered, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

def list_accounts(status=None, auth_type=None, screen_name=None, limit=None, cursor=None, include_secrets=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    accounts = _load("accounts.json")
    feeds = _load("feeds_and_searches.json")

    def _log(status_s, code=None, message=None, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "fs_" + hashlib.sha1(f"list_accounts|{now_iso}|{latency_ms}".encode("utf-8")).hexdigest()[:20],
            "account_id": None,
            "kind": "trends",  # request log piggyback (no separate audit collection)
            "subject_user_x_id": None,
            "query": "list_accounts",
            "cursor": cursor if isinstance(cursor, str) else None,
            "result_tweet_x_ids": None,
            "result_topics": None,
            "response_meta": {"endpoint": "list_accounts", "status": status_s, "error": {"code": code, "message": message} if code else None, "extra": extra, "latency_ms": latency_ms},
            "status": "failed" if status_s != "ok" else "fresh",
            "fetched_at": now_iso,
            "expires_at": None,
            "error": {"code": code, "message": message} if code else None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        feeds.append(row)
        _save("feeds_and_searches.json", feeds)

    # Authorization: allow enumeration only if there exists at least one active account.
    # (Ambient auth; no caller identity in params; best possible check with given store.)
    if not any(a.get("status") == "active" for a in accounts):
        _log("error", "UNAUTHORIZED", "Caller lacks permission to enumerate accounts")
        return _err("UNAUTHORIZED", "Caller lacks permission to enumerate accounts")

    # Validate filters
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "revoked", "expired", "disabled"):
            _log("error", "VALIDATION_ERROR", "Invalid status filter")
            return _err("VALIDATION_ERROR", "Invalid status filter")
    if auth_type is not None:
        # Tool enum says oauth2|cookie, but schema uses oauth2|oauth1a|session_cookie
        if not isinstance(auth_type, str) or auth_type not in ("oauth2", "cookie"):
            _log("error", "VALIDATION_ERROR", "Invalid auth_type filter")
            return _err("VALIDATION_ERROR", "Invalid auth_type filter")
    if screen_name is not None:
        if not isinstance(screen_name, str) or len(screen_name) < 1:
            _log("error", "VALIDATION_ERROR", "screen_name filter must be a non-empty string")
            return _err("VALIDATION_ERROR", "screen_name filter must be a non-empty string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR", "cursor must be a string")
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if include_secrets is None:
        include_secrets = False
    if not isinstance(include_secrets, bool):
        _log("error", "VALIDATION_ERROR", "include_secrets must be a boolean")
        return _err("VALIDATION_ERROR", "include_secrets must be a boolean")

    # Cursor format: xtcur_v1.<b64(json)>
    offset = 0
    if cursor is not None:
        if not cursor.startswith("xtcur_v1."):
            _log("error", "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        try:
            payload = base64.urlsafe_b64decode(cursor.split(".", 1)[1].encode("utf-8") + b"===")
            cur = json.loads(payload.decode("utf-8"))
        except Exception:
            _log("error", "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if not isinstance(cur, dict) or cur.get("kind") != "accounts" or not isinstance(cur.get("offset"), int) or cur["offset"] < 0:
            _log("error", "VALIDATION_ERROR", "cursor is invalid")
            return _err("VALIDATION_ERROR", "cursor is invalid")
        # Ensure cursor matches the same filters to avoid out-of-scope reuse
        if cur.get("status") != status or cur.get("auth_type") != auth_type or cur.get("screen_name") != (screen_name.lower() if isinstance(screen_name, str) else None) or cur.get("include_secrets") != include_secrets:
            _log("error", "VALIDATION_ERROR", "cursor is invalid/out of scope for the query")
            return _err("VALIDATION_ERROR", "cursor is invalid/out of scope for the query")
        offset = cur["offset"]

    # Filter
    rows = accounts[:]
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]
    if auth_type is not None:
        if auth_type == "oauth2":
            rows = [a for a in rows if a.get("auth_type") == "oauth2"]
        else:  # cookie
            rows = [a for a in rows if a.get("auth_type") == "session_cookie"]
    if screen_name is not None:
        s = screen_name.lower()
        rows = [a for a in rows if isinstance(a.get("screen_name"), str) and a.get("screen_name", "").lower() == s]

    # Sort by most recently updated
    def _key(a):
        return (a.get("updated_at") or "", a.get("created_at") or "", a.get("id") or "")
    rows.sort(key=_key, reverse=True)

    if offset > len(rows):
        _log("error", "VALIDATION_ERROR", "cursor offset out of range")
        return _err("VALIDATION_ERROR", "cursor offset out of range")

    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(rows)
    next_cursor = None
    if has_more:
        nxt = {
            "v": 1,
            "kind": "accounts",
            "offset": next_offset,
            "status": status,
            "auth_type": auth_type,
            "screen_name": screen_name.lower() if isinstance(screen_name, str) else None,
            "include_secrets": include_secrets,
        }
        token = base64.urlsafe_b64encode(json.dumps(nxt, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = "xtcur_v1." + token

    # Redaction
    def _redact(a):
        a2 = dict(a)
        if not include_secrets:
            a2.pop("access_token", None)
            a2.pop("refresh_token", None)
            a2.pop("cookie_jar", None)
        return a2

    out = [_redact(a) for a in page]
    _log("ok", extra={"returned": len(out), "total": len(rows)})
    return {
        "data": {"accounts": out, "cursor": next_cursor},
        "meta": {"limit": limit, "total": len(rows), "has_more": has_more},
    }

def create_account(auth_type, x_user_id=None, screen_name=None, display_name=None, access_token=None, refresh_token=None, token_expires_at=None, cookie_jar=None, status=None, replace=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_account"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _is_nonempty_str(v):
        return isinstance(v, str) and len(v) > 0

    def _b32_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # 20 chars gives good entropy; regex requires 17+
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(20))

    # Usage log / quota enforcement (if collection exists)
    usage_file = "request_logs.json"
    usage = _load(usage_file)
    now = _now()
    # Basic global rate limit: 120 req/min across all callers (no explicit credential)
    try:
        cutoff = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)).isoformat()
        recent = 0
        for r in usage:
            ts = r.get("timestamp")
            if isinstance(ts, str) and ts >= cutoff:
                recent += 1
        if recent >= 120:
            # log refused call
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "RATE_LIMIT", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
    except Exception:
        # if usage malformed, don't crash; treat as no rate limit, but still proceed
        pass

    # Validate inputs
    if auth_type not in ("oauth2", "cookie"):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "auth_type must be one of: oauth2, cookie.", field="auth_type")

    if x_user_id is not None and not _is_nonempty_str(x_user_id):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "x_user_id must be a non-empty string when provided.", field="x_user_id")

    if screen_name is not None and not _is_nonempty_str(screen_name):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "screen_name must be a non-empty string when provided.", field="screen_name")

    if display_name is not None and not isinstance(display_name, str):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "display_name must be a string when provided.", field="display_name")

    parsed_exp = None
    if token_expires_at is not None:
        parsed_exp = _parse_dt(token_expires_at)
        if parsed_exp is None:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", "token_expires_at must be RFC3339 date-time.", field="token_expires_at")

    if status is None:
        status = "active"
    if status not in ("active", "revoked", "expired", "disabled"):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "status must be one of: active, revoked, expired, disabled.", field="status")

    if replace is not None and not isinstance(replace, bool):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "replace must be boolean when provided.", field="replace")

    # Credential presence validation + "validate against X" approximation:
    # In offline store-backed service, we treat "validation" as requiring enough info to associate
    # to an existing users row OR to provided x_user_id+screen_name, and non-empty token/cookie data.
    if auth_type == "oauth2":
        if not _is_nonempty_str(access_token):
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", "access_token is required when auth_type=oauth2.", field="access_token")
    else:
        if not isinstance(cookie_jar, dict) or len(cookie_jar) == 0:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", "cookie_jar (non-empty object) is required when auth_type=cookie.", field="cookie_jar")

    if screen_name is not None:
        screen_name_norm = screen_name.strip()
        if screen_name_norm == "":
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", "screen_name cannot be empty.", field="screen_name")
        screen_name = screen_name_norm

    # Resolve/validate identity via users store when possible; else require both x_user_id and screen_name
    users = _load("users.json")
    resolved_user = None
    if x_user_id is not None:
        for u in users:
            if u.get("x_id") == x_user_id:
                resolved_user = u
                break
    if resolved_user is None and screen_name is not None:
        sn_l = screen_name.lower()
        for u in users:
            if isinstance(u.get("screen_name"), str) and u.get("screen_name").lower() == sn_l:
                resolved_user = u
                break

    if resolved_user is not None:
        # prefer store truth
        x_user_id = resolved_user.get("x_id")
        if x_user_id is None:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "UNAUTHORIZED", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("UNAUTHORIZED", "Credential could not be validated against X (missing user mapping).")
        screen_name = resolved_user.get("screen_name") or screen_name
        display_name = resolved_user.get("display_name") if resolved_user.get("display_name") is not None else display_name
    else:
        # cannot "validate against X" offline; require enough identity fields
        if not _is_nonempty_str(x_user_id) or not _is_nonempty_str(screen_name):
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "UNAUTHORIZED", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("UNAUTHORIZED", "Credential could not be validated against X; provide x_user_id and screen_name or preseed users store.")

    # Enforce constraints on accounts
    accounts = _load("accounts.json")

    # Unique(x_user_id, auth_type) where status in ('active','expired')
    def _auth_type_store(a):
        # schema supports oauth2/oauth1a/session_cookie; tool uses oauth2/cookie
        if auth_type == "cookie":
            return "session_cookie"
        return "oauth2"

    auth_type_store = _auth_type_store(auth_type)

    existing = None
    for a in accounts:
        if a.get("x_user_id") == x_user_id and a.get("auth_type") == auth_type_store and a.get("status") in ("active", "expired"):
            existing = a
            break

    created_at = _now()
    updated_at = created_at

    # token_expires_at constraint: null or > created_at
    if parsed_exp is not None:
        try:
            if parsed_exp <= _parse_dt(created_at):
                usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
                _save(usage_file, usage)
                return _err("VALIDATION_ERROR", "token_expires_at must be after created_at.", field="token_expires_at")
        except Exception:
            pass

    if not _is_nonempty_str(screen_name):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "screen_name is required after validation.", field="screen_name")

    # Replace / conflict behavior
    if existing is not None and not replace:
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": existing.get("id"), "status": "CONFLICT", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("CONFLICT", "An account for this x_user_id and auth_type already exists.", account_id=existing.get("id"))

    if existing is None:
        acct = {
            "id": _b32_id("xt_acct"),
            "x_user_id": x_user_id,
            "screen_name": screen_name,
            "display_name": display_name,
            "auth_type": auth_type_store,
            "access_token": access_token if auth_type == "oauth2" else None,
            "refresh_token": refresh_token if auth_type == "oauth2" else None,
            "token_expires_at": token_expires_at if auth_type == "oauth2" else None,
            "cookie_jar": cookie_jar if auth_type == "cookie" else None,
            "status": status,
            "last_used_at": None,
            "rate_limit_state": {"windows": {}, "created_at": created_at},
            "created_at": created_at,
            "updated_at": updated_at,
        }
        accounts.append(acct)
        _save("accounts.json", accounts)
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": acct["id"], "status": "OK", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return {"account": acct}
    else:
        # update in place
        existing["screen_name"] = screen_name
        existing["display_name"] = display_name
        existing["auth_type"] = auth_type_store
        if auth_type == "oauth2":
            existing["access_token"] = access_token
            existing["refresh_token"] = refresh_token
            existing["token_expires_at"] = token_expires_at
            existing["cookie_jar"] = None
        else:
            existing["cookie_jar"] = cookie_jar
            existing["access_token"] = None
            existing["refresh_token"] = None
            existing["token_expires_at"] = None
        existing["status"] = status
        existing["updated_at"] = _now()
        _save("accounts.json", accounts)
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": existing.get("id"), "status": "OK", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return {"account": existing}

def update_account(account_id, status=None, screen_name=None, display_name=None, access_token=None, refresh_token=None, token_expires_at=None, cookie_jar=None, rate_limit_state=None, validate=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_account"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b32_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(20))

    # usage log / rate limit
    usage_file = "request_logs.json"
    usage = _load(usage_file)
    now = _now()
    try:
        cutoff = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)).isoformat()
        recent = sum(1 for r in usage if isinstance(r.get("timestamp"), str) and r.get("timestamp") >= cutoff)
        if recent >= 120:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "RATE_LIMIT", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
    except Exception:
        pass

    if not isinstance(account_id, str) or re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{17,}$", account_id) is None:
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id if isinstance(account_id, str) else None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "account_id is invalid.", field="account_id")

    if status is not None and status not in ("active", "revoked", "expired", "disabled"):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "status must be one of: active, revoked, expired, disabled.", field="status")

    if screen_name is not None and (not isinstance(screen_name, str) or screen_name.strip() == ""):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "screen_name must be a non-empty string.", field="screen_name")

    if display_name is not None and not isinstance(display_name, str):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "display_name must be a string.", field="display_name")

    if access_token is not None and (not isinstance(access_token, str) or access_token == ""):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string.", field="access_token")

    if refresh_token is not None and not isinstance(refresh_token, str):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "refresh_token must be a string.", field="refresh_token")

    parsed_exp = None
    if token_expires_at is not None:
        parsed_exp = _parse_dt(token_expires_at)
        if parsed_exp is None:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", "token_expires_at must be RFC3339 date-time.", field="token_expires_at")

    if cookie_jar is not None and (not isinstance(cookie_jar, dict) or len(cookie_jar) == 0):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "cookie_jar must be a non-empty object when provided.", field="cookie_jar")

    if rate_limit_state is not None and not isinstance(rate_limit_state, dict):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "rate_limit_state must be an object.", field="rate_limit_state")

    if validate is not None and not isinstance(validate, bool):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "validate must be boolean when provided.", field="validate")

    accounts = _load("accounts.json")
    acct = None
    for a in accounts:
        if a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "NOT_FOUND", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)

    current_status = acct.get("status")
    transitions = {
        "active": ["revoked", "expired", "disabled"],
        "expired": ["active", "disabled"],
        "revoked": ["disabled"],
        "disabled": [],
    }
    # Decide if we are changing credentials/status (default validate behavior)
    cred_changed = any(v is not None for v in (access_token, refresh_token, token_expires_at, cookie_jar))
    status_changed = (status is not None and status != current_status)
    if validate is None and (cred_changed or status_changed):
        validate = True
    if validate is None:
        validate = False

    # Lifecycle transition validation
    if status_changed:
        allowed = transitions.get(current_status, [])
        if status not in allowed:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "INVALID_TRANSITION", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=current_status, to_status=status)

    # Credential-type enforcement
    auth_type = acct.get("auth_type")
    if auth_type == "oauth2":
        if cookie_jar is not None:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", "cookie_jar cannot be set on oauth2 accounts.", field="cookie_jar")
    elif auth_type == "session_cookie":
        if any(v is not None for v in (access_token, refresh_token, token_expires_at)):
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", "OAuth token fields cannot be set on cookie accounts.", field="access_token")

    # "Validate against X" approximation: ensure credentials present when activating or rotating
    if validate:
        if (status == "active") or cred_changed:
            if auth_type == "oauth2":
                token = access_token if access_token is not None else acct.get("access_token")
                if not isinstance(token, str) or token == "":
                    usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "UNAUTHORIZED", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
                    _save(usage_file, usage)
                    return _err("UNAUTHORIZED", "Credential validation failed (missing access_token).")
            if auth_type == "session_cookie":
                cj = cookie_jar if cookie_jar is not None else acct.get("cookie_jar")
                if not isinstance(cj, dict) or len(cj) == 0:
                    usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "UNAUTHORIZED", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
                    _save(usage_file, usage)
                    return _err("UNAUTHORIZED", "Credential validation failed (missing cookie_jar).")

    # Enforce token_expires_at constraint relative to created_at
    if parsed_exp is not None:
        ca = _parse_dt(acct.get("created_at")) if isinstance(acct.get("created_at"), str) else None
        if ca is not None and parsed_exp <= ca:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", "token_expires_at must be after created_at.", field="token_expires_at")

    # Unique(x_user_id, auth_type) where status in ('active','expired')
    prospective_status = status if status is not None else current_status
    if prospective_status in ("active", "expired"):
        for other in accounts:
            if other.get("id") == account_id:
                continue
            if other.get("x_user_id") == acct.get("x_user_id") and other.get("auth_type") == auth_type and other.get("status") in ("active", "expired"):
                usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "CONFLICT", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
                _save(usage_file, usage)
                return _err("CONFLICT", "Updating would violate unique(x_user_id, auth_type) among active/expired accounts.", conflicting_account_id=other.get("id"))

    # Apply updates
    if status is not None:
        acct["status"] = status
    if screen_name is not None:
        acct["screen_name"] = screen_name.strip()
    if display_name is not None:
        acct["display_name"] = display_name
    if auth_type == "oauth2":
        if access_token is not None:
            acct["access_token"] = access_token
        if refresh_token is not None:
            acct["refresh_token"] = refresh_token
        if token_expires_at is not None:
            acct["token_expires_at"] = token_expires_at
    if auth_type == "session_cookie":
        if cookie_jar is not None:
            acct["cookie_jar"] = cookie_jar
    if rate_limit_state is not None:
        acct["rate_limit_state"] = rate_limit_state

    if not isinstance(acct.get("screen_name"), str) or acct.get("screen_name") == "":
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "screen_name cannot be empty.", field="screen_name")

    acct["updated_at"] = _now()
    _save("accounts.json", accounts)
    usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "OK", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
    _save(usage_file, usage)
    return {"account": acct}

def list_tweets(account_id=None, author_user_x_id=None, conversation_x_id=None, status=None, since=None, until=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, secrets, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_tweets"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b32_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(20))

    usage_file = "request_logs.json"
    usage = _load(usage_file)
    now = _now()
    try:
        cutoff = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)).isoformat()
        recent = sum(1 for r in usage if isinstance(r.get("timestamp"), str) and r.get("timestamp") >= cutoff)
        if recent >= 240:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "RATE_LIMIT", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
    except Exception:
        pass

    if account_id is not None:
        if not isinstance(account_id, str) or re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{17,}$", account_id) is None:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id if isinstance(account_id, str) else None, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", "account_id is invalid.", field="account_id")

    if author_user_x_id is not None and (not isinstance(author_user_x_id, str) or author_user_x_id == ""):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "author_user_x_id must be a non-empty string.", field="author_user_x_id")

    if conversation_x_id is not None and (not isinstance(conversation_x_id, str) or conversation_x_id == ""):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "conversation_x_id must be a non-empty string.", field="conversation_x_id")

    if status is not None and status not in ("visible", "deleted", "withheld", "tombstoned"):
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "status must be one of: visible, deleted, withheld, tombstoned.", field="status")

    since_dt = _parse_dt(since) if since is not None else None
    if since is not None and since_dt is None:
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "since must be RFC3339 date-time.", field="since")

    until_dt = _parse_dt(until) if until is not None else None
    if until is not None and until_dt is None:
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "until must be RFC3339 date-time.", field="until")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    # Cursor is base64url encoded JSON: {"offset": int}
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            offset = int(obj.get("offset", 0))
            if offset < 0:
                raise ValueError()
        except Exception:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    tweets = _load("tweets.json")
    users = _load("users.json")
    user_by_xid = {u.get("x_id"): u for u in users if isinstance(u, dict)}

    # If returning protected users' tweets, require account context
    needs_auth = False
    if author_user_x_id is not None:
        u = user_by_xid.get(author_user_x_id)
        if u and u.get("protected") is True:
            needs_auth = True

    if needs_auth:
        # Must have an active account to view protected content
        accounts = _load("accounts.json")
        acct_ok = None
        if account_id is not None:
            for a in accounts:
                if a.get("id") == account_id and a.get("status") == "active":
                    acct_ok = a
                    break
        else:
            for a in accounts:
                if a.get("status") == "active":
                    acct_ok = a
                    break
        if acct_ok is None:
            usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "UNAUTHORIZED", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
            _save(usage_file, usage)
            return _err("UNAUTHORIZED", "An active authenticated account is required to list protected content.")

    # Filtering
    def _tweet_created_dt(t):
        # Prefer created_on_x_at; fallback created_at
        v = t.get("created_on_x_at") or t.get("created_at")
        if not isinstance(v, str):
            return None
        return _parse_dt(v)

    filtered = []
    for t in tweets:
        if not isinstance(t, dict):
            continue
        if author_user_x_id is not None and t.get("author_user_x_id") != author_user_x_id:
            continue
        if conversation_x_id is not None and t.get("conversation_x_id") != conversation_x_id:
            continue
        if status is not None and t.get("status") != status:
            continue
        if since_dt is not None or until_dt is not None:
            d = _tweet_created_dt(t)
            if d is None:
                continue
            if since_dt is not None and d < since_dt:
                continue
            if until_dt is not None and d >= until_dt:
                continue
        filtered.append(t)

    # Sort newest first by created_on_x_at then created_at then x_id
    def _sort_key(t):
        d = _tweet_created_dt(t)
        if d is None:
            d = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (d, str(t.get("x_id") or ""), str(t.get("id") or ""))

    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        raw = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    usage.append({"id": _b32_id("xt_req"), "endpoint": endpoint, "account_id": account_id, "status": "OK", "latency_ms": int((time.time()-t0)*1000), "timestamp": now})
    _save(usage_file, usage)
    return {"tweets": page, "meta": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more}}

def set_tweet_status(tweet_id=None, x_tweet_id=None, status=None, deleted_on_x_at=None, allow_resurrect=None, reason=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "set_tweet_status"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _reqlog(status_s, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _gen_id("xt_req_"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1]
            dt = datetime.datetime.fromisoformat(ss)
            return dt
        except Exception:
            return None

    # Validate
    if status not in ("visible", "deleted", "withheld", "tombstoned"):
        _reqlog("error", error_code="VALIDATION_ERROR", error_message="Invalid status.")
        return _err("VALIDATION_ERROR", "status is required and must be one of: visible, deleted, withheld, tombstoned.", field="status")

    if tweet_id is None and x_tweet_id is None:
        _reqlog("error", error_code="VALIDATION_ERROR", error_message="tweet_id or x_tweet_id required.")
        return _err("VALIDATION_ERROR", "Either tweet_id or x_tweet_id must be provided.", field="tweet_id")

    if tweet_id is not None:
        if not isinstance(tweet_id, str) or re.fullmatch(r"^xt_twt_[0-9A-HJKMNP-TV-Z]{17,}$", tweet_id) is None:
            _reqlog("error", error_code="VALIDATION_ERROR", error_message="tweet_id malformed.")
            return _err("VALIDATION_ERROR", "tweet_id is malformed.", field="tweet_id")
    if x_tweet_id is not None:
        if not isinstance(x_tweet_id, str) or not x_tweet_id.strip():
            _reqlog("error", error_code="VALIDATION_ERROR", error_message="x_tweet_id must be non-empty.")
            return _err("VALIDATION_ERROR", "x_tweet_id must be a non-empty string.", field="x_tweet_id")

    if allow_resurrect is not None and not isinstance(allow_resurrect, bool):
        _reqlog("error", error_code="VALIDATION_ERROR", error_message="allow_resurrect must be boolean.")
        return _err("VALIDATION_ERROR", "allow_resurrect must be a boolean.", field="allow_resurrect")
    if reason is not None and not isinstance(reason, str):
        _reqlog("error", error_code="VALIDATION_ERROR", error_message="reason must be string.")
        return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")

    del_dt = None
    if deleted_on_x_at is not None:
        del_dt = _parse_dt(deleted_on_x_at)
        if del_dt is None:
            _reqlog("error", error_code="VALIDATION_ERROR", error_message="deleted_on_x_at must be RFC3339 date-time.")
            return _err("VALIDATION_ERROR", "deleted_on_x_at must be an ISO8601 date-time string.", field="deleted_on_x_at")

    tweets = _load("tweets.json")
    if not isinstance(tweets, list): tweets = []

    tw = None
    for t in tweets:
        if tweet_id is not None and t.get("id") == tweet_id:
            tw = t
            break
        if tweet_id is None and x_tweet_id is not None and t.get("x_id") == x_tweet_id.strip():
            tw = t
            break

    if tw is None:
        _reqlog("error", error_code="NOT_FOUND", error_message="Tweet not found.")
        return _err("NOT_FOUND", "Tweet not found.")

    transitions = {
        "visible": {"deleted", "withheld", "tombstoned"},
        "withheld": {"tombstoned"},
        "tombstoned": set(),
        "deleted": set(),
    }
    cur = tw.get("status")
    if cur not in transitions:
        _reqlog("error", error_code="CONFLICT", error_message="Unknown current status.", meta={"current_status": cur})
        return _err("CONFLICT", "Tweet has an unknown current status.", current_status=cur)

    if status == cur:
        # idempotent: still apply deleted_on_x_at if needed
        if status == "deleted" and tw.get("deleted_on_x_at") is None:
            tw["deleted_on_x_at"] = (del_dt.isoformat() + "Z") if del_dt else now_iso
            tw["updated_at"] = now_iso
            _save("tweets.json", tweets)
        _reqlog("ok", meta={"idempotent": True, "tweet_id": tw.get("id"), "x_id": tw.get("x_id")})
        return {"tweet": tw}

    # Prevent resurrection of deleted without allow_resurrect
    if cur == "deleted" and status == "visible" and not allow_resurrect:
        _reqlog("error", error_code="CONFLICT", error_message="Refusing to resurrect deleted tweet without allow_resurrect.")
        return _err("CONFLICT", "Refusing to resurrect a deleted tweet without allow_resurrect=true.", field="allow_resurrect")

    if status not in transitions[cur] and not (cur == "deleted" and status == "visible" and allow_resurrect):
        _reqlog("error", error_code="INVALID_TRANSITION", error_message="Illegal status transition.", meta={"from": cur, "to": status})
        return _err("INVALID_TRANSITION", "Illegal tweet status transition.", from_status=cur, to_status=status)

    tw["status"] = status
    if status == "deleted":
        tw["deleted_on_x_at"] = (del_dt.isoformat() + "Z") if del_dt else now_iso
    else:
        # keep deleted_on_x_at only if still deleted; enforce constraint
        if tw.get("deleted_on_x_at") is not None and status != "deleted":
            # if resurrecting allowed, clear deleted_on_x_at
            tw["deleted_on_x_at"] = None
    tw["updated_at"] = now_iso
    _save("tweets.json", tweets)

    _reqlog("ok", meta={"tweet_id": tw.get("id"), "x_id": tw.get("x_id"), "from": cur, "to": status, "reason": reason})
    return {"tweet": tw}

def get_auth_context(account_id=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0051000" if __import__("os").path.isdir("./environment_mix/0051000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _reqlog(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "xt_req_" + uuid.uuid4().hex,
            "endpoint": "get_auth_context",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    # Validate optional account_id but accept both patterns used across tools + datastore
    if account_id is not None:
        if not isinstance(account_id, str):
            _reqlog("error", credential_id=None, error_code="VALIDATION_ERROR", error_message="account_id must be a string.", meta={"field": "account_id"})
            return _err("VALIDATION_ERROR", "account_id must be a string.", field="account_id")
        if not (re.match(r"^xt_acct_[0-9A-HJKMNP-TV-Z]{17,}$", account_id) or re.match(r"^xt_acct_01H[0-9A-Z]{15,}$", account_id)):
            _reqlog("error", credential_id=account_id, error_code="VALIDATION_ERROR", error_message="account_id does not match required pattern.", meta={"field": "account_id"})
            return _err("VALIDATION_ERROR", "account_id does not match required pattern.", field="account_id")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    target = None
    if account_id is not None:
        target = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
        if not target:
            _reqlog("error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="Account context not found.")
            return _err("UNAUTHORIZED", "Account context not found.")
    else:
        # Ambient auth: choose any active account that is usable (has linked user)
        for a in accounts:
            if not isinstance(a, dict) or a.get("status") != "active":
                continue
            xu = a.get("x_user_id")
            if isinstance(xu, str) and any(isinstance(u, dict) and u.get("x_id") == xu for u in users):
                target = a
                break
        if target is None:
            target = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active"), None)

    if not target or target.get("status") != "active":
        _reqlog("error", credential_id=account_id, error_code="UNAUTHORIZED", error_message="No active authenticated context available.")
        return _err("UNAUTHORIZED", "No active authenticated context available.")

    xu = target.get("x_user_id")
    user = next((u for u in users if isinstance(u, dict) and u.get("x_id") == xu), None) if isinstance(xu, str) else None

    # Provide a simple snapshot of local throttles
    rls = target.get("rate_limit_state") if isinstance(target.get("rate_limit_state"), dict) else {}

    target["last_used_at"] = now_iso
    target["updated_at"] = now_iso
    _save("accounts.json", accounts)

    _reqlog("success", credential_id=target.get("id"), meta={"account_id": target.get("id")})
    return {
        "account": target,
        "user": user,
        "scopes": None,
        "rate_limit_state": rls,
    }
